package com.rikkeibank.account.repository; import com.rikkeibank.account.model.BankAccount; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import jakarta.persistence.LockModeType; import java.util.*; public interface BankAccountRepository extends JpaRepository<BankAccount,Long>{@Lock(LockModeType.PESSIMISTIC_WRITE) @Query("select a from BankAccount a where a.id=:id") Optional<BankAccount> findByIdForUpdate(@Param("id") Long id);List<BankAccount> findAllByOwnerUsername(String ownerUsername);}